CREATE TABLE IF NOT EXISTS governed_submissions(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,submission_ref TEXT NOT NULL,jurisdiction TEXT NOT NULL,consent_reference TEXT NOT NULL,rule_version TEXT,model_version TEXT,pricing_version TEXT,status TEXT NOT NULL DEFAULT 'intake',requested_limit NUMERIC(14,2) NOT NULL,evidence JSONB NOT NULL DEFAULT '[]'::jsonb,explanation TEXT,decision JSONB,adverse_notice JSONB,authority_actor_id BIGINT,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_by BIGINT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,submission_ref),UNIQUE(tenant_id,idempotency_key),CHECK(status IN ('intake','verified','evaluated','referred','authority_review','approved','declined','bound','issued')),CHECK(requested_limit>=0));
CREATE TABLE IF NOT EXISTS submission_exposures(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,submission_id BIGINT NOT NULL REFERENCES governed_submissions(id),field_name TEXT NOT NULL,field_value JSONB NOT NULL,source TEXT NOT NULL,verified_at TIMESTAMPTZ NOT NULL,checksum TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,submission_id,field_name,checksum));
CREATE TABLE IF NOT EXISTS underwriting_validation_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,rule_version TEXT NOT NULL,model_version TEXT NOT NULL,calibration JSONB NOT NULL,fairness JSONB NOT NULL,drift JSONB NOT NULL,approved_by BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS underwriting_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL,external_reference TEXT,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('queued','succeeded','failed','manual_review')));
CREATE TABLE IF NOT EXISTS underwriting_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,before_state JSONB,after_state JSONB,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
